INSERT INTO "categories" ("id", "name", "description", "active") VALUES (1, 'Limits Risk', 'Maneuvers through complex situations and anticipates risks, while charting a path that avoids negative outcomes and achieves solutions with appropriate governance.', TRUE) ON CONFLICT DO NOTHING;
INSERT INTO "categories" ("id", "name", "description", "active") VALUES (2, 'Embraces Agility', 'Navigates changing situations and priorities. Thrives in change, anticipates and seizes opportunities, and adjusts behavior to empower teams.', TRUE) ON CONFLICT DO NOTHING;
INSERT INTO "categories" ("id", "name", "description", "active") VALUES (3, 'Achieves Excellence', 'Takes ownership and applies fiscal accountability and sound judgement in managing resources in order to achieve the best project possible outcomes.', TRUE) ON CONFLICT DO NOTHING;
INSERT INTO "categories" ("id", "name", "description", "active") VALUES (4, 'Develops Relationships', 'Builds strong relationships, creates safe spaces for diverse perspectives, and aligns the drivers of motivation with organisational priorities to promote productivity and build cohesion.', TRUE) ON CONFLICT DO NOTHING;
INSERT INTO "categories" ("id", "name", "description", "active") VALUES (5, 'Sets Purpose', 'Aligns diverse perspectives and voices, creating a shared vision, which instills confidence and inspires others. Connects stories and datapoints. Communicates results and creates a clear call to action.', TRUE) ON CONFLICT DO NOTHING;
INSERT INTO "capabilities" ("id", "name", "description", "active") VALUES (1, 'Communicates Clarity', 'Creates shared understanding and meaning by delivering concise and well articulated communications to diverse groups', TRUE) ON CONFLICT DO NOTHING;
INSERT INTO "capabilities" ("id", "name", "description", "active") VALUES (2, 'Creates Alliances', 'Establishes relationships with key partners and builds and maintains engagement', TRUE) ON CONFLICT DO NOTHING;
INSERT INTO "capabilities" ("id", "name", "description", "active") VALUES (3, 'Demonstrates Empathy', 'Fosters collaboration by listening and withholding judgement to create safe spaces to share perspectives', TRUE) ON CONFLICT DO NOTHING;
INSERT INTO "capabilities" ("id", "name", "description", "active") VALUES (4, 'Develops Talent', 'Actively supports self and team growth through investing in formal and informal development methods', TRUE) ON CONFLICT DO NOTHING;
INSERT INTO "capabilities" ("id", "name", "description", "active") VALUES (5, 'Drives Performance and Productivity', 'Navigates competing priorities, aligns objectives, and defines tasks and milestones to achieve organizational goals', TRUE) ON CONFLICT DO NOTHING;
INSERT INTO "capabilities" ("id", "name", "description", "active") VALUES (6, 'Embraces Diversity', 'Brings different perspectives to the table, confronts bias and addressing systemic barriers to inclusion and accessibility', TRUE) ON CONFLICT DO NOTHING;
INSERT INTO "capabilities" ("id", "name", "description", "active") VALUES (7, 'Empowers Team Effectiveness', 'Creates resilient ecosystems by aligning and connecting team members through shared goals and resources', TRUE) ON CONFLICT DO NOTHING;
INSERT INTO "capabilities" ("id", "name", "description", "active") VALUES (8, 'Establishes Governance', 'Works with stakeholders to ensure accountability, ethical behaviour, fairness and transparency', TRUE) ON CONFLICT DO NOTHING;
INSERT INTO "capabilities" ("id", "name", "description", "active") VALUES (9, 'Evolves With Technology', 'Embraces the use of new technologies to improve efficiency, spur transformational change and seize opportunities', TRUE) ON CONFLICT DO NOTHING;
INSERT INTO "capabilities" ("id", "name", "description", "active") VALUES (10, 'Exercises Sound Judgement/Consulting', 'Makes decisions by using a balanced mix of analysis, big picture thinking and expertise, while maintaining objectivity', TRUE) ON CONFLICT DO NOTHING;
