INSERT INTO "email_templates" ("id", "template_key", "name", "subject", "preheader", "heading", "body_html", "button_label", "button_url", "image_url", "brand_primary", "brand_accent", "updated_at", "enabled") VALUES (1, 'upgrade_1', 'Snapshot upgrade 1', 'Go beyond your snapshot, {{first_name}}', 'Your next level of capability insight is ready.', 'Your snapshot is the beginning', '<p>Hi {{first_name}},</p><p>Your free snapshot showed the pattern across your five LEADS pillars. The Full Assessment goes further with the complete 93-question experience, capability-level detail, career benchmarks, industry best-fit, learning recommendations, and the full career toolkit.</p><p>When you are ready for a more complete picture, your next step is waiting.</p>', 'Explore the Full Assessment', 'https://app.orginsights.io/', NULL, '#075d46', '#a9ddc5', 1791295944000, 1) ON CONFLICT DO NOTHING;
INSERT INTO "email_templates" ("id", "template_key", "name", "subject", "preheader", "heading", "body_html", "button_label", "button_url", "image_url", "brand_primary", "brand_accent", "updated_at", "enabled") VALUES (2, 'upgrade_2', 'Snapshot upgrade 2', 'Save 25% on your Full Assessment', 'Use UPGRADE25 to move beyond your free snapshot.', 'A clearer picture, now 25% off', '<p>Hi {{first_name}},</p><p>Your snapshot identified the broad themes. The Full Assessment helps you see the capabilities inside each pillar and gives you practical tools for your next career move.</p><p>Use code <strong>UPGRADE25</strong> at checkout to save 25% on the Full Assessment.</p>', 'Use UPGRADE25', 'https://app.orginsights.io/', NULL, '#075d46', '#a9ddc5', 1791295944000, 1) ON CONFLICT DO NOTHING;
INSERT INTO "email_templates" ("id", "template_key", "name", "subject", "preheader", "heading", "body_html", "button_label", "button_url", "image_url", "brand_primary", "brand_accent", "updated_at", "enabled") VALUES (3, 'upgrade_3', 'Snapshot upgrade 3', 'Your 25% upgrade offer is still available', 'UPGRADE25 is ready when you want deeper insight.', 'Turn your snapshot into a complete evidence map', '<p>Hi {{first_name}},</p><p>Your five-pillar snapshot is a useful starting point. The complete assessment adds the detail you need to explain your strengths with greater confidence.</p><p>Enter <strong>UPGRADE25</strong> at checkout for 25% off the Full Assessment.</p>', 'Upgrade with 25% off', 'https://app.orginsights.io/', NULL, '#075d46', '#a9ddc5', 1791295944000, 1) ON CONFLICT DO NOTHING;
INSERT INTO "email_templates" ("id", "template_key", "name", "subject", "preheader", "heading", "body_html", "button_label", "button_url", "image_url", "brand_primary", "brand_accent", "updated_at", "enabled") VALUES (4, 'upgrade_4', 'Snapshot upgrade 4', 'A 50% Full Assessment offer for you', 'Use UPGRADE50 for your biggest upgrade saving.', 'Go deeper for half the price', '<p>Hi {{first_name}},</p><p>If you want more than a directional snapshot, this is a strong time to continue. The Full Assessment gives you the complete question set, detailed report, benchmarks, best-fit insights, learning recommendations, and career toolkit.</p><p>Use code <strong>UPGRADE50</strong> at checkout to save 50% on the Full Assessment.</p>', 'Use UPGRADE50', 'https://app.orginsights.io/', NULL, '#075d46', '#a9ddc5', 1791295944000, 1) ON CONFLICT DO NOTHING;
INSERT INTO "email_templates" ("id", "template_key", "name", "subject", "preheader", "heading", "body_html", "button_label", "button_url", "image_url", "brand_primary", "brand_accent", "updated_at", "enabled") VALUES (5, 'upgrade_5', 'Snapshot upgrade 5', 'Your 50% Full Assessment offer is waiting', 'UPGRADE50 is still available.', 'Build the evidence behind your next move', '<p>Hi {{first_name}},</p><p>The strongest career decisions start with evidence. Your Full Assessment can reveal the detailed capability pattern behind the five pillars in your snapshot.</p><p>Use <strong>UPGRADE50</strong> at checkout for 50% off.</p>', 'Upgrade with 50% off', 'https://app.orginsights.io/', NULL, '#075d46', '#a9ddc5', 1791295944000, 1) ON CONFLICT DO NOTHING;
INSERT INTO "email_templates" ("id", "template_key", "name", "subject", "preheader", "heading", "body_html", "button_label", "button_url", "image_url", "brand_primary", "brand_accent", "updated_at", "enabled") VALUES (6, 'upgrade_6', 'Snapshot upgrade 6', 'Last chance to use your 50% upgrade offer', 'A final reminder about UPGRADE50.', 'One final chance to complete the picture', '<p>Hi {{first_name}},</p><p>This is your final reminder to move from the free snapshot to the Full Assessment at 50% off.</p><p>Use code <strong>UPGRADE50</strong> at checkout to unlock the complete assessment, detailed report, and career toolkit.</p>', 'Use UPGRADE50', 'https://app.orginsights.io/', NULL, '#075d46', '#a9ddc5', 1791295944000, 1) ON CONFLICT DO NOTHING;
INSERT INTO "email_templates" ("id", "template_key", "name", "subject", "preheader", "heading", "body_html", "button_label", "button_url", "image_url", "brand_primary", "brand_accent", "updated_at", "enabled") VALUES (7, 'welcome', 'Welcome', 'Welcome to OrgInsights, {{first_name}}', 'Your assessment path is ready.', 'Your capability journey starts here', '<p>Hi {{first_name}},</p><p>Welcome to OrgInsights. Your assessment workspace is ready.</p><p>Start with the Self-Assessment, then complete the OrgInsights work-context assessment. Choose the answer that best reflects your usual behaviour, and trust your first honest response.</p><ul><li>Find a quiet moment without interruptions.</li><li>Your progress saves as you go.</li><li>Use the Assessment Guide whenever you want more context.</li></ul><p>When both sections are complete, your report will be ready in your workspace.</p>', 'Start my assessment', 'https://app.orginsights.io/', NULL, '#075d46', '#a9ddc5', 1791488196087, 1) ON CONFLICT DO NOTHING;
INSERT INTO "email_templates" ("id", "template_key", "name", "subject", "preheader", "heading", "body_html", "button_label", "button_url", "image_url", "brand_primary", "brand_accent", "updated_at", "enabled") VALUES (8, 'nudge_1', 'Start nudge 1', 'Ready when you are, {{first_name}}', 'Your first assessment is waiting.', 'Take the first step', '<p>Hi {{first_name}},</p><p>Your OrgInsights assessment path is ready whenever you are. Most people find it easiest to begin with one focused block of time and answer from instinct.</p><p>Start with the Self-Assessment. Your progress will save as you go.</p>', 'Begin the Self-Assessment', 'https://app.orginsights.io/', NULL, '#075d46', '#a9ddc5', 1791488196110, 1) ON CONFLICT DO NOTHING;
INSERT INTO "email_templates" ("id", "template_key", "name", "subject", "preheader", "heading", "body_html", "button_label", "button_url", "image_url", "brand_primary", "brand_accent", "updated_at", "enabled") VALUES (9, 'nudge_2', 'Start nudge 2', 'A clearer view of your capabilities is waiting', 'Begin your assessment when you have a few focused minutes.', 'Turn experience into evidence', '<p>Hi {{first_name}},</p><p>Your experience already contains evidence of how you lead, adapt, build relationships, manage risk, and deliver results. The assessment helps you see that pattern more clearly.</p><p>Begin when you have a quiet moment. There are no right or wrong answers.</p>', 'Continue to OrgInsights', 'https://app.orginsights.io/', NULL, '#075d46', '#a9ddc5', 1791488196130, 1) ON CONFLICT DO NOTHING;
INSERT INTO "email_templates" ("id", "template_key", "name", "subject", "preheader", "heading", "body_html", "button_label", "button_url", "image_url", "brand_primary", "brand_accent", "updated_at", "enabled") VALUES (10, 'nudge_3', 'Start nudge 3', 'Your OrgInsights workspace is still open', 'Your assessment has not been started yet.', 'Your next move can start with clarity', '<p>Hi {{first_name}},</p><p>A strong career story starts with knowing what you can do and where that capability shows up. Your OrgInsights workspace is still ready for you.</p><p>Set aside a focused block of time, answer honestly, and let the pattern emerge.</p>', 'Start now', 'https://app.orginsights.io/', NULL, '#075d46', '#a9ddc5', 1791488196159, 1) ON CONFLICT DO NOTHING;
INSERT INTO "email_templates" ("id", "template_key", "name", "subject", "preheader", "heading", "body_html", "button_label", "button_url", "image_url", "brand_primary", "brand_accent", "updated_at", "enabled") VALUES (11, 'nudge_4', 'Final start nudge', 'Final reminder to begin your OrgInsights assessment', 'Your assessment path is still available.', 'One final reminder', '<p>Hi {{first_name}},</p><p>This is our final reminder that your OrgInsights assessment is waiting.</p><p>If understanding your strengths and development priorities is still useful, your workspace is ready. You can begin with the Self-Assessment and return to your saved progress later.</p>', 'Open my workspace', 'https://app.orginsights.io/', NULL, '#075d46', '#a9ddc5', 1791488196178, 1) ON CONFLICT DO NOTHING;
INSERT INTO "email_templates" ("id", "template_key", "name", "subject", "preheader", "heading", "body_html", "button_label", "button_url", "image_url", "brand_primary", "brand_accent", "updated_at", "enabled") VALUES (12, 'reminder_1', 'Completion reminder 1', 'Pick up where you left off', 'Your assessment progress is saved.', 'Your progress is waiting', '<p>Hi {{first_name}},</p><p>You have started your OrgInsights assessment, and your answers are saved.</p><p>Return when you have a focused moment. Completing both sections will unlock your report and the tools that help you use your results.</p>', 'Continue my assessment', 'https://app.orginsights.io/', NULL, '#075d46', '#a9ddc5', 1791488196198, 1) ON CONFLICT DO NOTHING;
INSERT INTO "email_templates" ("id", "template_key", "name", "subject", "preheader", "heading", "body_html", "button_label", "button_url", "image_url", "brand_primary", "brand_accent", "updated_at", "enabled") VALUES (13, 'reminder_2', 'Completion reminder 2', 'Keep building your capability picture', 'Continue from your saved progress.', 'You are already underway', '<p>Hi {{first_name}},</p><p>You have already done the hardest part, getting started. Continue from your saved progress and complete the remaining questions at your own pace.</p><p>Honest, instinctive answers create the most useful reflection.</p>', 'Resume my assessment', 'https://app.orginsights.io/', NULL, '#075d46', '#a9ddc5', 1791488196217, 1) ON CONFLICT DO NOTHING;
INSERT INTO "email_templates" ("id", "template_key", "name", "subject", "preheader", "heading", "body_html", "button_label", "button_url", "image_url", "brand_primary", "brand_accent", "updated_at", "enabled") VALUES (14, 'reminder_3', 'Completion reminder 3', 'Your saved OrgInsights assessment is ready to continue', 'Return to the questions you have left.', 'Finish the picture', '<p>Hi {{first_name}},</p><p>Your partial assessment gives you a starting point. Completing both sections turns those individual answers into a connected view of your five LEADS pillars.</p><p>Your saved progress is ready when you are.</p>', 'Continue where I stopped', 'https://app.orginsights.io/', NULL, '#075d46', '#a9ddc5', 1791488196239, 1) ON CONFLICT DO NOTHING;
INSERT INTO "email_templates" ("id", "template_key", "name", "subject", "preheader", "heading", "body_html", "button_label", "button_url", "image_url", "brand_primary", "brand_accent", "updated_at", "enabled") VALUES (15, 'reminder_4', 'Completion reminder 4', 'A few more answers can unlock your report', 'Your progress remains saved.', 'Bring your results together', '<p>Hi {{first_name}},</p><p>Your OrgInsights report becomes available after both assessment sections are complete.</p><p>Return to your saved workspace, finish the remaining questions, and see the pattern across your results.</p>', 'Finish my assessment', 'https://app.orginsights.io/', NULL, '#075d46', '#a9ddc5', 1791488196260, 1) ON CONFLICT DO NOTHING;
INSERT INTO "email_templates" ("id", "template_key", "name", "subject", "preheader", "heading", "body_html", "button_label", "button_url", "image_url", "brand_primary", "brand_accent", "updated_at", "enabled") VALUES (16, 'reminder_5', 'Final completion reminder', 'Final reminder to complete your OrgInsights assessment', 'Your saved assessment is still available.', 'Complete what you started', '<p>Hi {{first_name}},</p><p>This is our final completion reminder. Your assessment progress is still saved, and your report will be ready after both sections are complete.</p><p>If the insight still matters to you, return when you can give the remaining questions your attention.</p>', 'Complete my assessment', 'https://app.orginsights.io/', NULL, '#075d46', '#a9ddc5', 1791488196281, 1) ON CONFLICT DO NOTHING;
INSERT INTO "email_templates" ("id", "template_key", "name", "subject", "preheader", "heading", "body_html", "button_label", "button_url", "image_url", "brand_primary", "brand_accent", "updated_at", "enabled") VALUES (17, 'thank_you', 'Completion thank you', 'Your OrgInsights report is ready', 'Thank you for completing your assessment.', 'Your capability evidence map is ready', '<p>Hi {{first_name}},</p><p>Thank you for completing your OrgInsights assessment.</p><p>Your report is now available in your workspace. Review your strongest signals, your development focus, and the practical tools that can help you turn insight into action.</p>', 'View my report', '{{report_url}}', NULL, '#075d46', '#a9ddc5', 1791488196302, 1) ON CONFLICT DO NOTHING;
INSERT INTO "email_templates" ("id", "template_key", "name", "subject", "preheader", "heading", "body_html", "button_label", "button_url", "image_url", "brand_primary", "brand_accent", "updated_at", "enabled") VALUES (18, 'report_360_ready', '360 report ready', 'Your 360 report is ready, {{first_name}}', 'Your 360 feedback is complete.', 'Your 360 feedback is complete', '<p>Hi {{first_name}},</p><p>Everyone you invited has shared their feedback, and your 360 report is now ready. See how others experience your capabilities alongside your own view, including your hidden talents and blind spots.</p>', 'View my 360 report', 'https://app.orginsights.io/?view=reports&report=360', NULL, '#075d46', '#a9ddc5', 1791488196321, 1) ON CONFLICT DO NOTHING;
INSERT INTO "email_templates" ("id", "template_key", "name", "subject", "preheader", "heading", "body_html", "button_label", "button_url", "image_url", "brand_primary", "brand_accent", "updated_at", "enabled") VALUES (19, 'stalled_360_1', 'Stalled 360 nudge 1', 'Your 360 is waiting on more responses', 'A quick personal follow-up can help complete your 360.', 'Give your raters a nudge', '<p>Hi {{first_name}},</p><p>Your 360 is underway and {{completed_count}} of your raters have responded so far. A quick personal follow-up goes a long way. Your report unlocks once at least 3 raters have completed.</p>', 'Check my 360 progress', 'https://app.orginsights.io/?view=raters', NULL, '#075d46', '#a9ddc5', 1791488196341, 1) ON CONFLICT DO NOTHING;
INSERT INTO "email_templates" ("id", "template_key", "name", "subject", "preheader", "heading", "body_html", "button_label", "button_url", "image_url", "brand_primary", "brand_accent", "updated_at", "enabled") VALUES (20, 'stalled_360_2', 'Stalled 360 nudge 2', 'Still waiting on your 360 feedback, {{first_name}}', 'Your report still needs at least 3 completed raters.', 'Your 360 needs a push', '<p>Hi {{first_name}},</p><p>Your 360 report is still waiting. Only {{completed_count}} raters have responded and you need at least 3 for your report. Reach out to your raters directly, people usually just need a reminder.</p>', 'Check my 360 progress', 'https://app.orginsights.io/?view=raters', NULL, '#075d46', '#a9ddc5', 1791488196362, 1) ON CONFLICT DO NOTHING;
INSERT INTO "email_templates" ("id", "template_key", "name", "subject", "preheader", "heading", "body_html", "button_label", "button_url", "image_url", "brand_primary", "brand_accent", "updated_at", "enabled") VALUES (21, 'payment_receipt', 'Payment receipt', 'Your OrgInsights receipt', 'Your payment is confirmed and access is active.', 'Payment confirmed', '<p>Hi {{first_name}},</p><p>Thank you for your purchase. Order details: {{tier_name}}, {{amount_paid}}, {{order_date}}. Your access is active for one full year from today.</p>', 'Start my assessment', 'https://app.orginsights.io/', NULL, '#075d46', '#a9ddc5', 1791488196398, 1) ON CONFLICT DO NOTHING;
INSERT INTO "email_templates" ("id", "template_key", "name", "subject", "preheader", "heading", "body_html", "button_label", "button_url", "image_url", "brand_primary", "brand_accent", "updated_at", "enabled") VALUES (22, 'forgot_password', 'Forgot password', 'Reset your OrgInsights password', 'Your secure password reset link expires in one hour.', 'Reset your password', '<p>Hi {{first_name}},</p><p>We received a request to reset your OrgInsights password. Use the secure link below within one hour.</p><p>If you did not request this change, you can ignore this email. Your current password will continue to work.</p>', 'Set a new password', '{{reset_url}}', NULL, '#075d46', '#a9ddc5', 1791488196421, 1) ON CONFLICT DO NOTHING;
INSERT INTO "email_templates" ("id", "template_key", "name", "subject", "preheader", "heading", "body_html", "button_label", "button_url", "image_url", "brand_primary", "brand_accent", "updated_at", "enabled") VALUES (23, 'password_changed', 'Password changed', 'Your OrgInsights password was changed', 'Your account password has been updated.', 'Password updated', '<p>Hi {{first_name}},</p><p>Your OrgInsights password was changed by an administrator.</p><p>If you expected this change, no action is required. If you did not expect it, request a new password from the sign-in screen or contact OrgInsights support.</p>', 'Open OrgInsights', 'https://app.orginsights.io/', NULL, '#075d46', '#a9ddc5', 1791488196443, 1) ON CONFLICT DO NOTHING;
INSERT INTO "email_templates" ("id", "template_key", "name", "subject", "preheader", "heading", "body_html", "button_label", "button_url", "image_url", "brand_primary", "brand_accent", "updated_at", "enabled") VALUES (24, 'expiry_warning_30', 'Access expiry warning, 30 days', 'Your OrgInsights access expires in 30 days', 'Your paid assessment access is ending soon.', 'Your access is ending soon', '<p>Hi {{first_name}},</p><p>Your {{tier_name}} access expires on {{expiry_date}}. Your completed reports will always be available, but you will need a new plan to take further assessments after that date.</p>', 'View plans', 'https://app.orginsights.io/?view=pricing', NULL, '#075d46', '#a9ddc5', 1791488196464, 1) ON CONFLICT DO NOTHING;
INSERT INTO "email_templates" ("id", "template_key", "name", "subject", "preheader", "heading", "body_html", "button_label", "button_url", "image_url", "brand_primary", "brand_accent", "updated_at", "enabled") VALUES (25, 'expiry_warning_7', 'Access expiry warning, 7 days', '7 days left on your OrgInsights access', 'One week remains on your paid assessment access.', 'One week remaining', '<p>Hi {{first_name}},</p><p>Just a reminder that your {{tier_name}} access expires on {{expiry_date}}. Your reports stay available, but further assessments will need a new plan.</p>', 'View plans', 'https://app.orginsights.io/?view=pricing', NULL, '#075d46', '#a9ddc5', 1791488196486, 1) ON CONFLICT DO NOTHING;
INSERT INTO "email_templates" ("id", "template_key", "name", "subject", "preheader", "heading", "body_html", "button_label", "button_url", "image_url", "brand_primary", "brand_accent", "updated_at", "enabled") VALUES (26, 'coach_candidate_completed', 'Coach candidate completed', '{{candidate_name}} completed their OrgInsights assessment', 'Your candidate''s private results are ready.', 'Your candidate has finished', '<p>Hi {{coach_name}},</p><p>{{candidate_name}} has completed their {{tier_name}} assessment. Use the private link below to review their results. No login is required. As a reminder, the candidate was told at registration that you can see their answers.</p>', 'View candidate results', '{{coach_results_url}}', NULL, '#075d46', '#a9ddc5', 1791488196508, 1) ON CONFLICT DO NOTHING;
INSERT INTO "email_templates" ("id", "template_key", "name", "subject", "preheader", "heading", "body_html", "button_label", "button_url", "image_url", "brand_primary", "brand_accent", "updated_at", "enabled") VALUES (27, 'no_raters_1', 'No raters invited nudge 1', 'Invite your raters to unlock your 360', 'Your 360 assessment is ready for rater invitations.', 'Your 360 needs raters', '<p>Hi {{first_name}},</p><p>Your 360 assessment is ready, but you have not invited any raters yet. Invite 3 to 10 people who know your work well. Your report unlocks once at least 3 of them have responded.</p>', 'Invite raters', 'https://app.orginsights.io/?view=raters', NULL, '#075d46', '#a9ddc5', 1791488196529, 1) ON CONFLICT DO NOTHING;
INSERT INTO "email_templates" ("id", "template_key", "name", "subject", "preheader", "heading", "body_html", "button_label", "button_url", "image_url", "brand_primary", "brand_accent", "updated_at", "enabled") VALUES (28, 'no_raters_2', 'No raters invited nudge 2', '{{first_name}}, your 360 is waiting for raters', 'Invite 3 to 10 raters to start your 360.', 'Do not leave your 360 empty', '<p>Hi {{first_name}},</p><p>You have the 360 tier but no raters invited yet, so nothing is in motion. Pick 3 to 10 colleagues, mentors, or managers and send the invites today. It takes two minutes.</p>', 'Invite raters', 'https://app.orginsights.io/?view=raters', NULL, '#075d46', '#a9ddc5', 1791488196554, 1) ON CONFLICT DO NOTHING;
INSERT INTO "rater_email_templates" ("id", "template_key", "name", "subject", "preheader", "heading", "body_html", "button_label", "brand_primary", "brand_accent", "updated_at", "enabled", "button_url") VALUES (1, 'rater_invite', 'Initial rater invitation', '{{candidate_name}} invited you to provide 360 feedback', 'Your private OrgInsights feedback link is ready.', 'Share what you have observed', '<p>Hi {{rater_name}},</p><p>{{candidate_name}} has invited you to provide private 360 feedback through OrgInsights.</p><p>Please answer based on the behaviour you have personally observed. Your unique link does not require a login.</p>', 'Give feedback', '#075d46', '#a9ddc5', 1791488153000, 1, '{{assessment_link}}') ON CONFLICT DO NOTHING;
INSERT INTO "rater_email_templates" ("id", "template_key", "name", "subject", "preheader", "heading", "body_html", "button_label", "brand_primary", "brand_accent", "updated_at", "enabled", "button_url") VALUES (2, 'rater_reminder_1', 'Rater reminder 1', 'Reminder: feedback for {{candidate_name}}', 'Your private feedback link is still open.', 'Your perspective is still needed', '<p>Hi {{rater_name}},</p><p>This is a reminder to complete the OrgInsights 360 feedback requested by {{candidate_name}}.</p><p>Your unique link is still active. Please answer from your direct experience.</p>', 'Continue feedback', '#075d46', '#a9ddc5', 1791488155000, 1, '{{assessment_link}}') ON CONFLICT DO NOTHING;
INSERT INTO "rater_email_templates" ("id", "template_key", "name", "subject", "preheader", "heading", "body_html", "button_label", "brand_primary", "brand_accent", "updated_at", "enabled", "button_url") VALUES (3, 'rater_reminder_2', 'Rater reminder 2', 'Please complete your feedback for {{candidate_name}}', 'A short reminder from OrgInsights.', 'Help complete the 360 view', '<p>Hi {{rater_name}},</p><p>{{candidate_name}} is still waiting for your 360 feedback.</p><p>Please use your private link when you have a focused moment. You can return to saved answers until you submit.</p>', 'Resume feedback', '#075d46', '#a9ddc5', 1791488155000, 1, '{{assessment_link}}') ON CONFLICT DO NOTHING;
INSERT INTO "rater_email_templates" ("id", "template_key", "name", "subject", "preheader", "heading", "body_html", "button_label", "brand_primary", "brand_accent", "updated_at", "enabled", "button_url") VALUES (4, 'rater_reminder_3', 'Ongoing rater reminder', 'Your 360 feedback link for {{candidate_name}} is still open', 'Complete the feedback requested by your colleague.', 'One more reminder', '<p>Hi {{rater_name}},</p><p>Your OrgInsights feedback request from {{candidate_name}} remains open.</p><p>Reminders stop as soon as you submit or the candidate closes the 360 assessment.</p>', 'Complete feedback', '#075d46', '#a9ddc5', 1791488155000, 1, '{{assessment_link}}') ON CONFLICT DO NOTHING;
INSERT INTO "rater_email_templates" ("id", "template_key", "name", "subject", "preheader", "heading", "body_html", "button_label", "brand_primary", "brand_accent", "updated_at", "enabled", "button_url") VALUES (5, 'rater_thank_you', 'Rater thank-you', 'Thank you for your feedback', 'Your 360 feedback has been submitted.', 'Thank you', '<p>Hi {{rater_name}},</p><p>Thank you for completing the 360 feedback for {{candidate_name}}. Your honest perspective is what makes their report meaningful. Your responses are kept anonymous.</p>', '', '#075d46', '#a9ddc5', 1791488171213, 1, '') ON CONFLICT DO NOTHING;
